const bytes=hex=>Uint8Array.from(hex.match(/../g),s=>parseInt(s,16));
const read=(b,a,n)=>Array.from({length:n},(_,i)=>b[(a+i)^1]);
const put=(b,a,code)=>{for(let i=0;i<code.length;i++)b[(a+i)^1]=code[i];};
export async function patchSceneROM(module){
 const rp='/system/fbneo/patched/mslug3fd.zip',bp='/system/fbneo/patched/neogeo.zip';
 const rom=await JSZip.loadAsync(module.FS.readFile(rp)),bios=await JSZip.loadAsync(module.FS.readFile(bp));
 const p1=await rom.file('256-ph1.p1').async('uint8array');
 for(const [at,expected,code]of data.hooks){
  if(String(read(p1,at,expected.length/2))!==String(bytes(expected)))throw Error('SCENE_HOOK_MISMATCH_'+at.toString(16));
  put(p1,at,bytes(code));
 }
 for(const name of ['sp-s2.sp1','sp-s3.sp1']){
  const b=await bios.file(name).async('uint8array'),sum=b.reduce((a,v)=>a+v,0);
  for(const [at,hex]of data.blocks){const code=bytes(hex);if(read(b,at,code.length).some(v=>v!==255))throw Error('SCENE_BIOS_SPACE_OCCUPIED');put(b,at,code);}
  b[0x10fff]=(b[0x10fff]+sum-b.reduce((a,v)=>a+v,0))&255;bios.file(name,b);
 }
 rom.file('256-ph1.p1',p1);
 const rpBytes=await rom.generateAsync({type:'uint8array',compression:'STORE'}),bpBytes=await bios.generateAsync({type:'uint8array',compression:'STORE'});
 module.FS.writeFile(rp,rpBytes);module.FS.writeFile(bp,bpBytes);
}
